<?php
// Shared admin/control authentication. No customer-session behavior is changed.
function security_db(): PDO {
 $d=db();static $done=false;if($done)return $d;$done=true;
 $d->exec("CREATE TABLE IF NOT EXISTS auth_attempts(k CHAR(64) PRIMARY KEY,cnt INT NOT NULL DEFAULT 0,window_at BIGINT NOT NULL,locked_until BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB");
 $d->exec("CREATE TABLE IF NOT EXISTS auth_activity(id BIGINT AUTO_INCREMENT PRIMARY KEY,panel VARCHAR(10) NOT NULL,username VARCHAR(120) NOT NULL,device VARCHAR(300) NOT NULL,result VARCHAR(30) NOT NULL,created_at BIGINT NOT NULL,INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $d->exec("CREATE TABLE IF NOT EXISTS auth_sessions(token_hash CHAR(64) PRIMARY KEY,panel VARCHAR(10) NOT NULL,principal VARCHAR(120) NOT NULL,username VARCHAR(120) NOT NULL,expires_at BIGINT NOT NULL,last_seen BIGINT NOT NULL,created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $d->exec("CREATE TABLE IF NOT EXISTS auth_totp(panel VARCHAR(10) NOT NULL,principal VARCHAR(120) NOT NULL,secret TEXT NOT NULL,enabled TINYINT NOT NULL DEFAULT 0,last_step BIGINT NOT NULL DEFAULT -1,recovery TEXT NOT NULL,PRIMARY KEY(panel,principal)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $d->exec("CREATE TABLE IF NOT EXISTS auth_challenges(token_hash CHAR(64) PRIMARY KEY,panel VARCHAR(10) NOT NULL,principal VARCHAR(120) NOT NULL,username VARCHAR(120) NOT NULL,remember TINYINT NOT NULL DEFAULT 0,expires_at BIGINT NOT NULL,attempts INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");return $d;
}
function auth_config():array {$n=fn($k,$default,$min,$max)=>max($min,min($max,(int)setting($k,(string)$default)?:$default));return ['failures'=>$n('auth_failure_limit',5,3,20),'lockMinutes'=>$n('auth_lock_minutes',15,1,120),'idleMinutes'=>$n('auth_idle_minutes',30,5,240),'rememberDays'=>$n('auth_remember_days',7,1,30)];}
function auth_now():int{return (int)floor(microtime(true)*1000);}
function auth_log(string $panel,string $username,string $device,string $result):void {security_db();q('INSERT INTO auth_activity(panel,username,device,result,created_at) VALUES(?,?,?,?,?)',[$panel,mb_substr($username,0,120),mb_substr($device,0,300),$result,auth_now()]);q('DELETE FROM auth_activity WHERE created_at<?',[auth_now()-90*86400000]);}
function auth_keys(string $panel,string $username,string $ip):array{return [hash('sha256',"$panel:account:".mb_strtolower(trim($username))),hash('sha256',"$panel:ip:$ip")];}
function auth_locked(string $panel,string $username,string $ip):int{security_db();$seconds=0;foreach(auth_keys($panel,$username,$ip) as $k){$r=qone('SELECT locked_until FROM auth_attempts WHERE k=?',[$k]);$seconds=max($seconds,(int)ceil((($r['locked_until']??0)-auth_now())/1000));}return $seconds;}
function auth_failure(string $panel,string $username,string $ip):int {$d=security_db();$now=auth_now();$c=auth_config();$d->beginTransaction();try{foreach(auth_keys($panel,$username,$ip) as $k){q('INSERT IGNORE INTO auth_attempts(k,cnt,window_at,locked_until) VALUES(?,0,?,0)',[$k,$now]);$r=qone('SELECT * FROM auth_attempts WHERE k=? FOR UPDATE',[$k]);$fresh=$now-(int)$r['window_at']>900000;$cnt=$fresh?1:(int)$r['cnt']+1;q('UPDATE auth_attempts SET cnt=?,window_at=?,locked_until=? WHERE k=?',[$cnt,$fresh?$now:$r['window_at'],$cnt>=$c['failures']?$now+$c['lockMinutes']*60000:0,$k]);}$d->commit();}catch(Throwable $e){$d->rollBack();throw $e;}q('DELETE FROM auth_attempts WHERE window_at<? AND locked_until<?',[$now-86400000,$now]);return auth_locked($panel,$username,$ip);}
function auth_success(string $panel,string $username,string $ip):void{security_db();foreach(auth_keys($panel,$username,$ip) as $k)q('DELETE FROM auth_attempts WHERE k=?',[$k]);}
function auth_make_session(string $panel,string $principal,string $username,bool $remember):string{security_db();$token=bin2hex(random_bytes(32));$now=auth_now();q('DELETE FROM auth_sessions WHERE expires_at<?',[$now]);q('INSERT INTO auth_sessions VALUES(?,?,?,?,?,?,?)',[hash('sha256',$token),$panel,$principal,$username,$now+($remember?auth_config()['rememberDays']:1)*86400000,$now,$now]);return $token;}
function auth_read_session(string $panel,string $token){security_db();if(!$token)return null;$h=hash('sha256',$token);$r=qone('SELECT * FROM auth_sessions WHERE token_hash=? AND panel=?',[$h,$panel]);if(!$r)return null;$now=auth_now();if((int)$r['expires_at']<=$now||(int)$r['last_seen']+auth_config()['idleMinutes']*60000<=$now){q('DELETE FROM auth_sessions WHERE token_hash=?',[$h]);return null;}if($now-(int)$r['last_seen']>15000)q('UPDATE auth_sessions SET last_seen=? WHERE token_hash=?',[$now,$h]);return $r;}
function auth_revoke(string $token):void{security_db();q('DELETE FROM auth_sessions WHERE token_hash=?',[hash('sha256',$token)]);}
function auth_revoke_principal(string $panel,string $principal):void{security_db();q('DELETE FROM auth_sessions WHERE panel=? AND principal=?',[$panel,$principal]);q('DELETE FROM auth_challenges WHERE panel=? AND principal=?',[$panel,$principal]);}
function auth_cookie(string $panel,string $token,bool $remember):void{unset($_SESSION['istore_'.$panel]);setcookie('istore_'.$panel,$token,['expires'=>$remember?time()+auth_config()['rememberDays']*86400:0,'path'=>'/','httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);}
function auth_key():string {
 $s=getenv('AUTH_ENCRYPTION_KEY')?: (defined('AUTH_ENCRYPTION_KEY')?AUTH_ENCRYPTION_KEY:'');
 if($s===''){
  // Keep encryption material outside the web document root and outside release archives.
  $doc=realpath($_SERVER['DOCUMENT_ROOT']??APP_ROOT)?:APP_ROOT;
  $dir=dirname($doc);$file=$dir.'/.istore-auth-'.substr(hash('sha256',APP_ROOT.'|'.DB_NAME),0,12).'.key';
  if(!is_file($file)){$h=@fopen($file,'x');if($h){chmod($file,0600);fwrite($h,bin2hex(random_bytes(32)));fclose($h);}}
  if(is_file($file))$s=trim((string)file_get_contents($file));
 }
 if(!preg_match('/^[a-f0-9]{64}$/i',$s))throw new RuntimeException('Encryption key not configured');return hex2bin($s);
}
function auth_totp_ready():bool{try{auth_key();return true;}catch(Throwable $e){return false;}}
function auth_encrypt(string $s):string{$iv=random_bytes(12);$tag='';$data=openssl_encrypt($s,'aes-256-gcm',auth_key(),OPENSSL_RAW_DATA,$iv,$tag);if($data===false)throw new RuntimeException('Encryption failed');return bin2hex($iv).'.'.bin2hex($data).'.'.bin2hex($tag);}
function auth_decrypt(string $s):string{[$iv,$data,$tag]=explode('.',$s);$out=openssl_decrypt(hex2bin($data),'aes-256-gcm',auth_key(),OPENSSL_RAW_DATA,hex2bin($iv),hex2bin($tag));if($out===false)throw new RuntimeException('Decryption failed');return $out;}
function auth_base32(string $buf):string{$abc='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits=0;$val=0;$out='';foreach(unpack('C*',$buf) as $b){$val=($val<<8)|$b;$bits+=8;while($bits>=5){$bits-=5;$out.=$abc[($val>>$bits)&31];}}if($bits)$out.=$abc[($val<<(5-$bits))&31];return $out;}
function auth_decode32(string $s):string{$abc='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits=0;$val=0;$out='';foreach(str_split($s) as $c){$i=strpos($abc,$c);if($i===false)throw new RuntimeException('Bad secret');$val=($val<<5)|$i;$bits+=5;if($bits>=8){$bits-=8;$out.=chr(($val>>$bits)&255);}}return $out;}
function auth_totp_at(string $secret,int $step):string{$h=hash_hmac('sha1',pack('N2',intdiv($step,4294967296),$step%4294967296),auth_decode32($secret),true);$o=ord($h[19])&15;$n=unpack('N',substr($h,$o,4))[1]&0x7fffffff;return str_pad((string)($n%1000000),6,'0',STR_PAD_LEFT);}
function auth_totp_enabled(string $panel,string $id):bool{security_db();return !empty(qone('SELECT enabled FROM auth_totp WHERE panel=? AND principal=?',[$panel,$id])['enabled']);}
function auth_totp_begin(string $panel,string $id,string $username):array {security_db();if(auth_totp_enabled($panel,$id))throw new RuntimeException('Already enabled');$secret=auth_base32(random_bytes(20));q('REPLACE INTO auth_totp(panel,principal,secret,enabled,last_step,recovery) VALUES(?,?,?,0,-1,?)',[$panel,$id,auth_encrypt($secret),'[]']);return ['secret'=>$secret,'uri'=>'otpauth://totp/'.rawurlencode("IStore:$panel:$username").'?secret='.$secret.'&issuer=IStore&algorithm=SHA1&digits=6&period=30'];}
function auth_totp_verify(string $panel,string $id,string $code,bool $pending=false):bool {$d=security_db();$d->beginTransaction();try{$r=qone('SELECT * FROM auth_totp WHERE panel=? AND principal=? FOR UPDATE',[$panel,$id]);if(!$r||(!$r['enabled']&&!$pending)){$d->commit();return false;}$code=trim($code);if($r['enabled']&&preg_match('/^[a-f0-9]{8}-[a-f0-9]{8}$/',$code)){$codes=json_decode($r['recovery'],true);$i=array_search(hash('sha256',$code),$codes,true);if($i===false){$d->commit();return false;}array_splice($codes,$i,1);q('UPDATE auth_totp SET recovery=? WHERE panel=? AND principal=?',[json_encode($codes),$panel,$id]);$d->commit();return true;}if(!preg_match('/^\d{6}$/',$code)){$d->commit();return false;}$secret=auth_decrypt($r['secret']);$current=intdiv(time(),30);for($step=$current-1;$step<=$current+1;$step++){if($step<=(int)$r['last_step'])continue;if(hash_equals(auth_totp_at($secret,$step),$code)){q('UPDATE auth_totp SET last_step=? WHERE panel=? AND principal=?',[$step,$panel,$id]);$d->commit();return true;}}$d->commit();return false;}catch(Throwable $e){$d->rollBack();throw $e;}}
function auth_totp_confirm(string $panel,string $id,string $code){if(auth_totp_enabled($panel,$id)||!auth_totp_verify($panel,$id,$code,true))return null;$codes=[];for($i=0;$i<8;$i++)$codes[]=bin2hex(random_bytes(4)).'-'.bin2hex(random_bytes(4));q('UPDATE auth_totp SET enabled=1,recovery=? WHERE panel=? AND principal=?',[json_encode(array_map(fn($c)=>hash('sha256',$c),$codes)),$panel,$id]);auth_revoke_principal($panel,$id);return $codes;}
function auth_totp_disable(string $panel,string $id,string $code):bool{if(!auth_totp_verify($panel,$id,$code))return false;q('DELETE FROM auth_totp WHERE panel=? AND principal=?',[$panel,$id]);auth_revoke_principal($panel,$id);return true;}
function auth_challenge(string $panel,string $id,string $username,bool $remember):string{security_db();$token=bin2hex(random_bytes(32));q('DELETE FROM auth_challenges WHERE expires_at<?',[auth_now()]);q('INSERT INTO auth_challenges VALUES(?,?,?,?,?,?,0)',[hash('sha256',$token),$panel,$id,$username,$remember?1:0,auth_now()+300000]);return $token;}
function auth_login_flow(string $panel,array $b):array{
 $ip=$_SERVER['REMOTE_ADDR']??'local';$device=$_SERVER['HTTP_USER_AGENT']??'';$username=mb_substr(trim((string)($b['username']??'')),0,120);$remember=!empty($b['remember']);$id='';
 if(!empty($b['challenge'])){security_db();$h=hash('sha256',(string)$b['challenge']);$c=qone('SELECT * FROM auth_challenges WHERE token_hash=? AND panel=? AND expires_at>? AND attempts<5',[$h,$panel,auth_now()]);if(!$c)return ['error'=>'انتهت خطوة التحقق، سجل الدخول مجددا','status'=>401];$username=$c['username'];$id=$c['principal'];$remember=!empty($c['remember']);$seconds=auth_locked($panel,$username,$ip);if($seconds)return ['error'=>'تم إيقاف المحاولات مؤقتا','retry_after'=>$seconds,'status'=>429];q('UPDATE auth_challenges SET attempts=attempts+1 WHERE token_hash=?',[$h]);if(!auth_totp_verify($panel,$id,(string)($b['code']??''))){$seconds=auth_failure($panel,$username,$ip);auth_log($panel,$username,$device,'totp_failed');return ['error'=>'رمز التحقق غير صحيح أو سبق استخدامه','status'=>$seconds?429:401,'retry_after'=>$seconds];}q('DELETE FROM auth_challenges WHERE token_hash=?',[$h]);
 }else{if($username===''||empty($b['password']))return ['error'=>'أدخل اسم المستخدم وكلمة المرور','status'=>400];$seconds=auth_locked($panel,$username,$ip);if($seconds)return ['error'=>'تم إيقاف المحاولات مؤقتا','retry_after'=>$seconds,'status'=>429];$panel==='admin'?admin_bootstrap():control_bootstrap();$table=$panel==='admin'?'admin_users':'control_users';$u=qone("SELECT * FROM $table WHERE username=?",[$username]);if(!$u||!password_verify((string)$b['password'],$u['pass_hash'])){$seconds=auth_failure($panel,$username,$ip);auth_log($panel,$username,$device,'failed');return ['error'=>$seconds?'تم إيقاف المحاولات مؤقتا':'بيانات الدخول غير صحيحة','status'=>$seconds?429:401,'retry_after'=>$seconds];}$id=(string)$u['id'];if(auth_totp_enabled($panel,$id))return ['requires_totp'=>true,'challenge'=>auth_challenge($panel,$id,$username,$remember)];}
 auth_success($panel,$username,$ip);auth_cookie($panel,auth_make_session($panel,$id,$username,$remember),$remember);auth_log($panel,$username,$device,'success');return ['ok'=>true];
}
